/**
 * An inline numbered link to a source, with a hover preview (`design/components/citation.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/citation.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import { MEMBER_PROVIDERS, useMember } from '@polymorph/angular'
import styles from '@polymorph/recipes/ai/citation.module.css'
import { HoverCard } from '../overlays/HoverCard'
import type { CitationSource } from './SourceList'

/** An inline numbered link to a source, with a hover preview: the inputs it takes, by the React member's prop names. */
export interface CitationProps {
  /**
   * The mark's one-based number in the reply's SourceList.
   */
  index: number
  /**
   * The source the mark refers to, whose `href` is the link target.
   */
  source: CitationSource
}

/** An inline numbered link to a source, with a hover preview. */
@Component({
  selector: 'pm-citation',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [HoverCard],
  // prettier-ignore
  template: `<pm-hover-card><!-- mark -->
<a
[attr.class]="e1()"
[attr.href]="e2()"
target="_blank"
rel="noreferrer"
[attr.aria-label]="e3()"
data-member="citation"
>{{ e4() }}</a>
<ng-container ngProjectAs="[slot=content]"><!-- preview -->
<span
[attr.class]="e5()"
><span
[attr.class]="e6()"
>{{ e7() }}</span>
@if (e8()) {<span
[attr.class]="e9()"
>{{ e10() }}</span>}
@if (e11()) {<span
[attr.class]="e12()"
>{{ e13() }}</span>}</span></ng-container></pm-hover-card>`,
})
export class Citation {
  /**
   * The mark's one-based number in the reply's SourceList.
   */
  readonly index = input.required<CitationProps['index']>()
  /**
   * The source the mark refers to, whose `href` is the link target.
   */
  readonly source = input.required<CitationProps['source']>()
  protected readonly $ = useMember({
    events: [],
    props: { index: () => this.index(), source: () => this.source() },
  })
  protected readonly $p = this.$.props

  protected e1() {
    return styles.mark
  }

  protected e2() {
    return this.$p.source.href
  }

  protected e3() {
    return `${this.$p.index}. ${this.$p.source.title}`
  }

  protected e4() {
    return this.$p.index
  }

  protected e5() {
    return styles.preview
  }

  protected e6() {
    return styles.previewTitle
  }

  protected e7() {
    return this.$p.source.title
  }

  protected e8() {
    return this.$p.source.domain !== undefined
  }

  protected e9() {
    if (!(this.$p.source.domain !== undefined)) return undefined as never
    return styles.previewDomain
  }

  protected e10() {
    if (!(this.$p.source.domain !== undefined)) return undefined as never
    return this.$p.source.domain
  }

  protected e11() {
    return this.$p.source.snippet !== undefined
  }

  protected e12() {
    if (!(this.$p.source.snippet !== undefined)) return undefined as never
    return styles.previewSnippet
  }

  protected e13() {
    if (!(this.$p.source.snippet !== undefined)) return undefined as never
    return this.$p.source.snippet
  }
}
